                break;
            }
            for i in 0..node.child_count() {
                if let Some(child) = node.child(i) {
                    stack.push(child);
                }
            }
        }
        let class = class_node.expect("class_definition not found");
        let bases = extract_inheritance(&class, src);

        // Assert
        assert!(
            bases.contains(&"Animal".to_string()),
            "expected Animal, got {:?}",
            bases
